class BowlingGame:
    def __init__(self):
        self.rolls = []
        self._frame = 0        # index of current frame (0..9)
        self._in_frame = 0     # rolls already recorded in current frame
        self._first = None     # first roll of current frame
        self._over = False

    def roll(self, pins):
        if self._over:
            raise Exception("Game is already over")
        if pins < 0 or pins > 10:
            raise Exception("Roll must knock down between 0 and 10 pins")
        self.rolls.append(pins)
        if self._frame < 9:
            self._roll_frames_1_to_9(pins)
        else:
            self._roll_final_frame(pins)

    def _roll_frames_1_to_9(self, pins):
        if self._in_frame == 0:
            self._first = pins
            self._in_frame = 1
            if pins == 10:  # strike: frame complete
                self._finish_frame()
        else:
            if pins > 10 - self._first:
                self.rolls.pop()
                raise Exception("Two rolls in a frame cannot score more than 10 pins")
            self._finish_frame()

    def _roll_final_frame(self, pins):
        if self._in_frame == 0:
            self._first = pins
            self._in_frame = 1
            if self._first == 10:
                return  # strike: two bonus rolls to come
        elif self._in_frame == 1:
            if self._first == 10:
                self._second = pins
                self._in_frame = 2
                if pins == 10:
                    return  # another strike: final roll unconstrained
                return  # otherwise final roll constrained by the bonus pair
            else:
                if pins > 10 - self._first:
                    self.rolls.pop()
                    raise Exception("Two rolls in a frame cannot score more than 10 pins")
                self._finish_frame()
                return
        else:
            # third roll: only reachable after a strike; if the first bonus
            # was not a strike, the two bonus rolls together <= 10 pins
            if getattr(self, "_second", None) is not None and self._second != 10:
                if pins > 10 - self._second:
                    self.rolls.pop()
                    raise Exception("Bonus rolls in the final frame cannot score more than 10 pins together")
            self._finish_frame()

    def _finish_frame(self):
        self._frame += 1
        self._in_frame = 0
        self._first = None
        if self._frame == 10:
            self._over = True

    def score(self):
        if not self._over:
            raise Exception("Cannot score a game that is not yet complete")
        total = 0
        i = 0
        for frame in range(10):
            if self.rolls[i] == 10:  # strike
                total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                i += 1
            elif self.rolls[i] + self.rolls[i + 1] == 10:  # spare
                total += 10 + self.rolls[i + 2]
                i += 2
            else:  # open frame
                total += self.rolls[i] + self.rolls[i + 1]
                i += 2
            if frame == 9:
                break
        return total

