def _roll_final_frame(self, pins):
    if self._in_frame == 0:
        self._first = pins
        self._in_frame = 1
    elif self._in_frame == 1:
        if self._first == 10:  # strike: two bonus rolls to come
            self._second = pins
            self._in_frame = 2
        else:
            if pins > 10 - self._first:
                self.rolls.pop()
                raise Exception("Two rolls in a frame cannot score more than 10 pins")
            if self._first + pins == 10:  # spare: one bonus roll to come
                self._second = pins
                self._in_frame = 2
                return
            self._finish_frame()
    else:
        # third roll: after a strike, if the first bonus roll was not a
        # strike, the two bonus rolls together may not exceed 10 pins
        if self._first == 10 and self._second != 10:
            if pins > 10 - self._second:
                self.rolls.pop()
                raise Exception("Bonus rolls in the final frame cannot score more than 10 pins together")
        self._finish_frame()
